from abc import ABC, abstractmethod

class SortAlgorithm(ABC):
    def __init__(self, data):
        self.data = list(data)

    @abstractmethod
    def sort(self):
        """Template step - implemented by concrete algorithm"""
        pass

    def compare(self, a, b):
        # default compare uses natural ordering
        return -1 if a < b else 1 if a > b else 0

    def swap(self, i, j):
        self.data[i], self.data[j] = self.data[j], self.data[i]

    def get_data(self):
        return self.data


class BubbleSort(SortAlgorithm):
    def sort(self):
        n = len(self.data)
        for i in range(n):
            for j in range(0, n - i - 1):
                if self.compare(self.data[j], self.data[j + 1]) > 0:
                    self.swap(j, j + 1)


class SelectionSort(SortAlgorithm):
    def sort(self):
        n = len(self.data)
        for i in range(n):
            min_idx = i
            for j in range(i + 1, n):
                if self.compare(self.data[j], self.data[min_idx]) < 0:
                    min_idx = j
            if min_idx != i:
                self.swap(i, min_idx)


